<script lang="ts">

  import {currencyAmount} from '#lib/client/finance.ts';
  import AiUsageSummary from './AiUsageSummary.svelte';
  import type {AppData,Row} from '#lib/client/types.ts';import {display,recordName,permitted} from '#lib/client/api.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';import StartGuide from './StartGuide.svelte';
  let {data}:{data:AppData}=$props();
  const can=(permission:string)=>permitted(data,permission)||permitted(data,permission+'.read');
  const employee=$derived(['Employee','Workshop','employee','workshop'].includes(data.context?.role||''));
  const canOrders=$derived(can('orders'));const canAgenda=$derived(can('dispatch')||employee);
  const today=$derived(new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Berlin'}).format(new Date()));
  const firstName=$derived(data.user?.name?.trim().split(' ')[0]||'');
  const berlinDay=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'});
  const todayKey=$derived(berlinDay.format(new Date(data.summary.dataAsOf??Date.now())));
  const agenda=$derived((data.related.dispatch_assignments??[]).filter((row:Row)=>berlinDay.format(new Date(row.starts_at))<=todayKey&&berlinDay.format(new Date(Date.parse(row.ends_at)-1))>=todayKey));
  const agendaCount=$derived(Number(agenda[0]?.today_count??agenda.length));
  const tasks=$derived(can('tasks')?(data.related?.tasks||data.summary?.tasks||[]):[]);
  const taskCount=$derived(can('tasks')?Number(data.summary?.openTasks??tasks.length):0);
  const orders=$derived(canOrders?(data.related?.orders||data.summary?.recentOrders||data.records||[]):[]);
  const warnings=$derived(data.summary?.warnings||data.related?.data_quality_issues||[]);
  const metrics=$derived(data.summary?.metrics||{});const approvedHours=$derived(data.summary?.approvedHours==null?'—':new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(Number(data.summary.approvedHours))+' h');
  const metricItems=$derived(employee?[{label:'Eigene Einsätze heute',value:agendaCount,caption:'Geplante Termine',href:'#tagesplanung'},{label:'Offene Rückmeldungen',value:taskCount,caption:'Ihre nächsten Schritte',href:'/tasks'},{label:'Freigegebene Stunden',value:approvedHours,caption:'Freigegebener Gesamtstand',href:'/time'},{label:'Urlaub verfügbar',value:data.summary?.leaveBalance!=null?`${data.summary.leaveBalance} T`:'—',caption:'Bestätigter Anspruch',href:'/leave'}]:[
    {permission:'orders',label:'Laufende Aufträge',value:metrics.activeOrders??data.summary?.activeOrders??orders.filter((o:Row)=>!['completed','closed','cancelled'].includes(o.status)).length,caption:'Alle berechtigten Vorgänge',href:'/orders'},
    {permission:'sales',label:'Angebote in Bearbeitung',value:metrics.openQuotes??data.summary?.openQuotes??'—',caption:'Entwurf, Prüfung oder offen',href:'/quotes'},
    {permission:'finance',label:'Offene Forderungen',value:data.summary.receivables?.length?data.summary.receivables.map((balance:Row)=>currencyAmount(balance.amount,balance.currency)).join(' · '):'0',caption:'Offene Beträge je Währung',href:'/receivables?status=open'},
    {permission:'tasks',label:'Offene Aufgaben',value:taskCount,caption:'Aufgaben und Rückfragen',href:'/tasks'},
    ...(!canOrders&&can('time')?[{permission:'time',label:'Freigegebene Stunden',value:approvedHours,caption:'Mein bestätigter Zeitstand',href:'/time'},{permission:'time',label:'Urlaub verfügbar',value:data.summary?.leaveBalance!=null?String(data.summary.leaveBalance)+' T':'—',caption:'Mein bestätigter Anspruch',href:'/leave'}]:[])
  ].filter(metric=>can(metric.permission)));
  const role=$derived(data.context?.role);
  const entry=$derived(employee?{href:'/time',label:'Zur Zeiterfassung'}
    :role==='Dispatcher'&&can('dispatch')?{href:'/dispatch?mode=month',label:'Einsatzplan öffnen'}
    :role==='Planner'&&can('planning')?{href:'/studio',label:'Planungsstudio öffnen'}
    :role==='Finance'&&can('finance')?{href:'/receivables?status=open',label:'Offene Forderungen prüfen'}
    :role==='HR'&&can('hr')?{href:'/team',label:'Team öffnen'}
    :taskCount?{href:'/tasks',label:'Aufgaben ansehen'}
    :can('crm')?{href:'/inquiries',label:'Anfragen bearbeiten'}
    :can('system')?{href:'/jobs',label:'Verarbeitung prüfen'}
    :can('reports')?{href:'/reports',label:'Auswertungen öffnen'}
    :{href:'/account',label:'Meinen Zugang öffnen'});
  const quickLinks=$derived((employee?[{permission:'time',href:'/time',icon:'clock',name:'Arbeitszeit erfassen'},{permission:'time',href:'/leave',icon:'calendar',name:'Urlaub beantragen'},{permission:'documents',href:'/documents',icon:'file',name:'Meine Arbeitsunterlagen'}]:[{permission:'crm',href:'/inquiries',icon:'plus',name:'Eine neue Anfrage aufnehmen'},{permission:'hr',href:'/team',icon:'users',name:'Team & Personalakten öffnen'},{permission:'planning',href:'/studio',icon:'pen',name:'Im Planungsstudio arbeiten'},{permission:'documents',href:'/documents',icon:'upload',name:'Dokumente aufnehmen'},{permission:'finance',href:'/supplier-invoices',icon:'file',name:'Eingangsbelege prüfen'},{permission:'time',href:'/time',icon:'clock',name:'Arbeitszeit erfassen'},{permission:'system',href:'/jobs',icon:'refresh',name:'Verarbeitung & Fehler prüfen'},{permission:'reports',href:'/reports',icon:'chart',name:'Auswertungen öffnen'}]).filter(link=>can(link.permission)).slice(0,4));
  function time(value:any){return value&&!Number.isNaN(Date.parse(value))?new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'}).format(new Date(value)):'—';}
</script>
{#snippet todayAgenda()}{#if agenda.length}<section class="panel" id="tagesplanung"><header class="panel-header"><div><h2>{employee?'Meine Einsätze heute':'Heute im Betrieb'}</h2><p>{agendaCount>agenda.length?`Die ersten ${agenda.length} von ${agendaCount} Einsätzen heute`:'Termine und Einsätze in zeitlicher Reihenfolge'}</p></div>{#if can('dispatch')}<a class="text-link" href="/dispatch">Einsatzplan<Icon name="arrow" size={14}/></a>{/if}</header><div class="agenda">{#each [...agenda].sort((a:Row,b:Row)=>String(a.start_at||a.starts_at).localeCompare(String(b.start_at||b.starts_at))) as appointment}<article class="agenda-row"><time class="agenda-time">{berlinDay.format(new Date(appointment.starts_at))<todayKey?'Seit Vortag':time(appointment.starts_at)}</time><div class="agenda-marker"></div><div><a class="agenda-title" href={can('dispatch')?`/dispatch/${appointment.id}`:`/orders/${appointment.order_id}`}>{recordName(appointment)}</a><p class="agenda-sub">{appointment.order_name||[appointment.order_number,appointment.order_title].filter(Boolean).join(' · ')||display(appointment.order_id,'order_id',data)}{appointment.location?` · ${appointment.location}`:''}</p>{#if appointment.status}<Status value={appointment.status}/>{/if}</div></article>{/each}</div></section>{:else}<section class="agenda-empty" id="tagesplanung" aria-label={employee?'Meine Einsätze heute':'Heute im Betrieb'}><Icon name="calendar" size={20}/><div><h3>Heute noch ohne feste Termine</h3><p>{employee?'Sobald Sie für heute eingeteilt sind, erscheint Ihr Einsatz hier.':'Neue Einsätze für Werkstatt, Aufmaß oder Montage können Sie im Einsatzplan anlegen.'}</p></div><a class="text-link" href={can('dispatch')?'/dispatch':'/orders'}>{can('dispatch')?'Zum Einsatzplan':'Meine Aufträge öffnen'}<Icon name="arrow" size={15}/></a></section>{/if}{/snippet}

<div class="page-heading dashboard-heading" data-tour="today-heading"><div><h1>Guten Tag{firstName?`, ${firstName}`:''}.</h1><p>{employee?'Ihre Einsätze, Arbeitsunterlagen und Zeiten für heute.':'Ihre Termine, Aufgaben und aktuellen Aufträge.'}</p></div><div class="dashboard-heading-actions"><div class="dashboard-date"><Icon name="calendar" size={15}/>{today}</div><a class="btn" href={entry.href}>{entry.label}<Icon name="arrow" size={15}/></a></div></div>
{#if !data.connected}<div class="notice warning"><Icon name="alert"/><div class="notice-content"><div class="notice-title">Der Betriebsbestand ist noch nicht verbunden</div><p>Verbinden Sie die Datenbank und schließen Sie die einmalige Einrichtung ab. Bis dahin werden keine Geschäftsdaten oder Zahlen vorgetäuscht.</p>{#if can('admin')}<a class="text-link mt" href="/settings">Einrichtung prüfen<Icon name="arrow" size={14}/></a>{/if}</div></div>{/if}

{#if !orders.length&&!tasks.length&&!agenda.length}<StartGuide {data}/>{/if}


{#if can('system')}<div class="notice info"><div>Technischer Überblick: Dienste, Konfiguration und letzte Verarbeitungen.<a class="text-link" href="/settings?tab=system">System & Dienste öffnen</a></div></div>{/if}
<div class="dashboard-columns" class:single-column={!canAgenda&&!canOrders}><div class="stack">{#if canAgenda&&agenda.length}{@render todayAgenda()}{/if}{#if canOrders}<section class="panel"><header class="panel-header"><div><h2>{employee?'Meine Aufträge':'Aktuelle Aufträge'}</h2><p>Der nächste Schritt bleibt sichtbar.</p></div><a class="text-link" href="/orders">Alle Aufträge<Icon name="arrow" size={14}/></a></header>{#if orders.length}<div class="table-scroll desktop-only"><table class="data-table"><thead><tr><th>Auftrag</th><th>Kunde / Objekt</th><th>Stand</th><th></th></tr></thead><tbody>{#each orders.slice(0,5) as order}<tr><td><a class="record-title" href={`/orders/${order.id}`}>{recordName(order)}</a>{#if order.number}<p class="record-subtitle">{order.number}</p>{/if}</td><td>{order.customer_name||display(order.customer_id,'customer_id',data)}</td><td><Status value={order.status||order.planning_status}/></td><td><a class="icon-button" href={`/orders/${order.id}`} aria-label={`${recordName(order)} öffnen`}><Icon name="chevron" size={16}/></a></td></tr>{/each}</tbody></table></div><div class="dashboard-order-cards mobile-only">{#each orders.slice(0,5) as order}<a class="dashboard-order" href={`/orders/${order.id}`} aria-label={`${recordName(order)} öffnen`}><div class="dashboard-order-copy"><strong>{recordName(order)}</strong><p>{order.number||'Auftrag'} · {order.customer_name||display(order.customer_id,'customer_id',data)}</p><Status value={order.status||order.planning_status}/></div><Icon name="chevron" size={18}/></a>{/each}</div>{:else}<div class="empty-state compact"><p>{employee?'Ihre zugewiesenen Aufträge erscheinen hier.':'Es sind noch keine Aufträge angelegt. Angenommene Angebote führen direkt in die Auftragsakte.'}</p><a class="text-link" href="/orders">Aufträge öffnen<Icon name="arrow" size={14}/></a></div>{/if}</section>{/if}{#if canAgenda&&!agenda.length}{@render todayAgenda()}{/if}</div><div class="stack">{#if can('tasks')||warnings.length}<section class="panel"><header class="panel-header"><h2>Das braucht Aufmerksamkeit</h2><span class="count">{taskCount+warnings.length}</span></header>{#each tasks.slice(0,4) as task}<a class="task-row" href={`/tasks/${task.id}`}><div class="task-icon"><Icon name="check" size={16}/></div><div><h3>{recordName(task)}</h3><p>{task.urgency||'Kein Termin festgelegt'} · {display(task.priority??'normal')} · {display(task.assigned_to,'assigned_to',data)}</p><p>{task.source_label||'Vorgangsbezug prüfen'}</p></div><Icon name="chevron" size={14} class="chevron"/></a>{/each}{#each warnings.slice(0,2) as warning}<a class="task-row" href={warning.href||(can('reports')?'/reports':entry.href)}><div class="task-icon"><Icon name="alert" size={16}/></div><div><h3>{typeof warning==='string'?warning:warning.title||warning.message||'Datenqualität prüfen'}</h3><p>{typeof warning==='object'?warning.description||'Grundlage vor Freigabe vervollständigen.':'Grundlage vor Freigabe vervollständigen.'}</p></div><Icon name="chevron" size={14} class="chevron"/></a>{/each}{#if !tasks.length&&!warnings.length}<div class="empty-state compact"><div class="empty-icon"><Icon name="check"/></div><h3>Ein klarer Arbeitsbereich</h3><p>Sobald Aufgaben oder offene Freigaben vorliegen, sehen Sie hier den nächsten Schritt.</p></div>{/if}</section>{/if}<section class="panel"><header class="panel-header"><h2>Direkt weiterarbeiten</h2></header><div class="quick-links">{#each quickLinks as link}<a class="quick-link" href={link.href}><Icon name={link.icon} size={17}/>{link.name}<Icon name="arrow" size={15}/></a>{/each}{#if !quickLinks.length}<a class="quick-link" href="/account"><Icon name="users" size={17}/>Meinen Zugang verwalten<Icon name="arrow" size={15}/></a>{/if}</div></section></div></div>
{#if metricItems.length}<div class="metric-strip dashboard-metrics" class:compact-metrics={metricItems.length<4}>{#each metricItems as metric}<a class="metric" href={metric.href}><div class="metric-label">{metric.label}</div><div class="metric-value">{metric.value}</div><div class="metric-caption">{metric.caption}</div></a>{/each}</div>{/if}
{#if can('admin.integrations')&&data.summary?.aiUsage}<div class="dashboard-usage"><AiUsageSummary usage={data.summary.aiUsage} compact/></div>{/if}
<div class="data-stamp"><Icon name="refresh" size={11}/>Datenstand: {(data.summary?.dataAsOf||data.summary?.asOf)?display(data.summary.dataAsOf||data.summary.asOf,'updated_at'):data.connected?'aktueller berechtigter Datenbestand':'noch keine Verbindung'} · Zeitzone Europe/Berlin</div>

<style>.dashboard-columns.single-column{grid-template-columns:minmax(0,1fr);max-width:900px}.dashboard-columns.single-column>.stack:first-child{display:none}.compact-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:760px){.compact-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
